<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operation Lockdown | Facilitator</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/system.css"></head>
<body><header><strong>OPERATION LOCKDOWN 2.0</strong><nav><a href="/">Mission Hub</a><a href="/leaderboard/">Leaderboard</a></nav></header><main class="system"><div class="eyebrow">Staff access</div><h1 class="hero">Facilitator Control</h1><p class="subtitle">Adjust timings, check team progress, collect a key manually if a workstation fails, or reset a test group. Changes are logged.</p>
<section class="system-card" id="authCard"><h2>Staff login</h2><form id="authForm"><label for="username">Username</label><input id="username" required autocomplete="username"><label for="password">Password</label><input id="password" type="password" required autocomplete="current-password"><div class="actions"><button class="action" type="submit">Sign in</button></div></form><p id="authMessage" class="message" role="status"></p></section>
<div id="controls" class="hidden"><section class="system-card"><div class="row"><h2>Session timer</h2><div class="pill" id="roundLabel">Rotation 1</div></div><div id="currentTimer" class="timer">--:--</div><div class="actions"><button id="startTimer" class="action">Start / resume</button><button id="pauseTimer" class="action secondary">Pause</button><button id="resetTimer" class="action secondary">Reset timer</button><button id="nextRound" class="action secondary">Next rotation</button><button id="resetRounds" class="action secondary">Restart rotations</button></div><div class="fieldgroup"><div><label for="minutes">Minutes per rotation</label><input id="minutes" type="number" min="5" max="60" value="30"></div><button id="setMinutes" class="action secondary">Set duration</button></div></section>
<section class="system-card"><h2>Group controls</h2><div class="fieldgroup"><div><label for="targetGroup">Group</label><select id="targetGroup"><option value="alpha">Alpha</option><option value="bravo">Bravo</option><option value="charlie">Charlie</option></select></div><div><label for="keyZone">Recovery key</label><select id="keyZone"><option value="train">AI Defence Activated</option><option value="fix">Portal Secured</option><option value="defend">Threat Contained</option></select></div></div><label for="overrideReason">Reason for manual award</label><input id="overrideReason" placeholder="e.g. Computer stopped working"><div class="actions"><button id="awardKey" class="action secondary">Award key manually</button><button id="resetGroup" class="action danger">Reset this group</button></div><p class="note">A manual key is for genuine technical problems, not a shortcut. Reset permanently erases that group's progress.</p></section>
<section class="system-card"><h2>Current group results</h2><div id="groupInfo">Loading…</div></section><p id="actionMessage" class="message" role="status"></p></div></main>
<script type="module" src="/assets/js/facilitator.js"></script></body></html>
